// @evidence F.declaration.unassociated:start
// 原型诊断扩展：该声明没有被入口、策略、候选配置或处理器引用。
// 声明本身不建立导出业务，也不授予 B0 中任何主体操作权限。
export const UNASSOCIATED_DECLARATION = Object.freeze({
  role: 'realm-purchase:auditor',
  permission: 'request.export',
  effect: 'allow',
});
// @evidence F.declaration.unassociated:end

export const REALM = 'realm-purchase';

// @evidence F.roles:start
export const ROLES = Object.freeze({
  employee: `${REALM}:employee`,
  manager: `${REALM}:manager`,
  readonly: `${REALM}:readonly`,
});

// 无角色继承；租户不是角色 ID 的组成部分。
export const USERS = Object.freeze([
  { id: 'u1', realm: REALM, tenant: 'T1', roles: [ROLES.employee] },
  { id: 'u2', realm: REALM, tenant: 'T1', roles: [ROLES.manager] },
  { id: 'u3', realm: REALM, tenant: 'T1', roles: [ROLES.readonly] },
  { id: 'u4', realm: REALM, tenant: 'T2', roles: [ROLES.manager] },
].map(user => Object.freeze({ ...user, roles: Object.freeze(user.roles) })));
// @evidence F.roles:end

// @evidence F.objects:start
export const REQUESTS = Object.freeze([
  { id: 'r1', owner: 'u1', tenant: 'T1', state: 'DRAFT', amount: 1000 },
  { id: 'r2', owner: 'u1', tenant: 'T1', state: 'SUBMITTED', amount: 1000 },
  { id: 'r3', owner: 'u1', tenant: 'T1', state: 'SUBMITTED', amount: 6000 },
  { id: 'r4', owner: 'u4', tenant: 'T2', state: 'SUBMITTED', amount: 1000 },
].map(Object.freeze));
// @evidence F.objects:end

{
  "name": "codecartia-purchase-demo",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "供 CodeCartia 体验原型阅读的 B0 合成采购工程",
  "scripts": {
    "start": "node server/index.js",
    "test": "node test/purchase.test.js",
    "evidence": "node scripts/build-evidence.mjs"
  },
  "engines": {
    "node": ">=20"
  }
}

import { createDemoSessions, establishDemoContext } from './auth.js';
import { createRepository } from './repository.js';
import { createReceiptSender } from './receipt.js';
import { loadWorkflow } from './workflow.js';
import { createHandlers } from './handlers.js';
import { createRoutes } from './routes.js';
import { DemoError } from './errors.js';

export function createPurchaseApp(options = {}) {
  const sessions = createDemoSessions(options.users);
  const repository = createRepository(options.requests);
  const receipt = createReceiptSender();
  const workflow = options.workflow ?? loadWorkflow();
  const handlers = createHandlers({ repository, receipt, workflow });
  const dispatch = createRoutes({ repository, handlers });

  return {
    // sessionToken 是宿主识别演示会话的参数；body 不参与认证或资源绑定。
    async handle({ method, path, sessionToken, body, receiptTarget }) {
      const context = Object.freeze({
        ...establishDemoContext(sessions, sessionToken),
        // 原型诊断扩展：宿主可提供运行时目的地，仅供内存模拟记录。
        receiptTarget: receiptTarget ?? 'demo-memory-inbox',
      });
      try {
        const result = await dispatch({ method, path, context });
        return { status: 200, body: result };
      } catch (error) {
        if (error instanceof DemoError) {
          return { status: error.status, body: { error: error.code, message: error.message } };
        }
        throw error;
      }
    },
    repository,
    receipt,
    workflow,
    reset() {
      repository.reset();
      receipt.reset();
    },
  };
}

// @evidence F.audit:start
// 提交与审批共用此函数；审计写入调用者的事务，而非独立提交。
export function recordAudit(tx, { action, principal, request }) {
  tx.appendAudit({
    action,
    actor: principal.id,
    realm: principal.realm,
    tenant: principal.tenant,
    requestId: request.id,
    state: request.state,
  });
}
// @evidence F.audit:end

import { REALM, USERS } from '../data/fixtures.js';
import { DemoError } from './errors.js';

// @evidence F.identity:start
// 合成认证：本地宿主预先建立演示会话。固定 token 可任意选择，不能用于生产。
export function createDemoSessions(users = USERS) {
  return new Map(users.map(user => {
    const principal = Object.freeze({
      id: user.id,
      realm: user.realm,
      tenant: user.tenant,
      roles: Object.freeze([...user.roles]),
      authenticated: true,
    });
    return [`demo-${user.id}`, Object.freeze({ principal, mode: 'synthetic-demo' })];
  }));
}

export function establishDemoContext(sessions, sessionToken) {
  return Object.freeze({ session: sessions.get(sessionToken) ?? null });
}

export function authenticate(context) {
  // 只读取宿主绑定的 session；不接收 body.userId/body.roles/body.tenant。
  const principal = context.session?.principal;
  if (!principal?.authenticated || principal.realm !== REALM) {
    throw new DemoError(401, 'AUTHENTICATION_REQUIRED', '需要有效的合成演示会话');
  }
  return principal;
}
// @evidence F.identity:end

export class DemoError extends Error {
  constructor(status, code, message) {
    super(message);
    this.name = 'DemoError';
    this.status = status;
    this.code = code;
  }
}

import { DemoError } from './errors.js';
import { recordAudit } from './audit.js';

export function createHandlers({ repository, receipt, workflow }) {
  // @evidence F.handler.submit:start
  function submit(principal, request) {
    if (request.state !== 'DRAFT') {
      throw new DemoError(409, 'INVALID_STATE', '只有 DRAFT 申请可以提交');
    }
    if (!(request.amount > 0)) {
      throw new DemoError(422, 'INVALID_AMOUNT', '提交金额必须大于 0 元');
    }
    // @evidence F.commit.submit:start
    const submitted = repository.transaction(tx => {
      const updated = tx.setState(request.id, 'SUBMITTED');
      recordAudit(tx, { action: 'request.submit', principal, request: updated });
      return updated;
    });
    // @evidence F.commit.submit:end
    return {
      request: submitted,
      nextCandidates: workflow.candidatesFor('审批人', submitted),
    };
  }
  // @evidence F.handler.submit:end

  // @evidence F.handler.approve:start
  async function approve(principal, request, receiptTarget) {
    if (request.state !== 'SUBMITTED') {
      throw new DemoError(409, 'INVALID_STATE', '只有 SUBMITTED 申请可以审批');
    }
    if (!(request.amount <= 5000)) {
      throw new DemoError(422, 'AMOUNT_LIMIT', '审批金额不能超过 5000 元');
    }
    // @evidence F.tx.approve:start
    const approved = repository.transaction(tx => {
      const updated = tx.setState(request.id, 'APPROVED');
      recordAudit(tx, { action: 'request.approve', principal, request: updated });
      return updated;
    });
    // @evidence F.tx.approve:end

    // @evidence F.receipt.after-commit:start
    let receiptStatus = 'sent';
    try {
      await receipt.send(approved, receiptTarget);
    } catch (error) {
      receipt.recordFailure(approved, error);
      receiptStatus = 'failed';
      // 事务已经提交；这里记录回执失败，不回滚 APPROVED 和审计。
    }
    // @evidence F.receipt.after-commit:end
    return {
      request: approved,
      receipt: { status: receiptStatus, mode: 'simulated' },
      observerCandidates: workflow.candidatesFor('观察者', approved),
    };
  }
  // @evidence F.handler.approve:end

  // @evidence F.handler.read:start
  function read(principal, request) {
    // request 由路由按同一 ID 从仓储读取，并已经通过对应读取策略。
    return {
      request,
      viewedBy: principal.id,
      applicantCandidates: workflow.candidatesFor('申请人', request),
      observerCandidates: workflow.candidatesFor('观察者', request),
    };
  }
  // @evidence F.handler.read:end

  return { submit, approve, read };
}

import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { createPurchaseApp } from './app.js';

const app = createPurchaseApp();
const files = new Map([
  ['/', ['../web/index.html', 'text/html; charset=utf-8']],
  ['/web/PurchasePage.js', ['../web/PurchasePage.js', 'text/javascript; charset=utf-8']],
  ['/web/api.js', ['../web/api.js', 'text/javascript; charset=utf-8']],
  ['/data/fixtures.js', ['../data/fixtures.js', 'text/javascript; charset=utf-8']],
]);

createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://127.0.0.1');
    const staticFile = files.get(url.pathname);
    if (req.method === 'GET' && staticFile) {
      const content = await readFile(new URL(staticFile[0], import.meta.url));
      res.writeHead(200, { 'content-type': staticFile[1], 'cache-control': 'no-store' });
      res.end(content);
      return;
    }

    // 演示动作只使用路由 ID，无需请求体；即使自报身份也不会参与授权。
    req.resume();
    const result = await app.handle({
      method: req.method,
      path: url.pathname,
      sessionToken: req.headers['x-demo-session'],
      receiptTarget: req.headers['x-demo-receipt-target'],
    });
    res.writeHead(result.status, { 'content-type': 'application/json; charset=utf-8' });
    res.end(JSON.stringify(result.body));
  } catch {
    res.writeHead(500, { 'content-type': 'application/json; charset=utf-8' });
    res.end(JSON.stringify({ error: 'DEMO_INTERNAL_ERROR', message: '合成演示处理异常' }));
  }
}).listen(4100, '127.0.0.1', () => {
  console.log('B0 合成采购工程：http://127.0.0.1:4100（重启恢复初始数据）');
});

import { ROLES } from '../data/fixtures.js';
import { DemoError } from './errors.js';

function requireAllowed(allowed, permission) {
  // B0：适用允许规则任一满足即允许；无匹配规则默认拒绝。
  if (!allowed) {
    throw new DemoError(403, 'FORBIDDEN', `未满足 ${permission} 的授权条件`);
  }
}

// @evidence F.policy.submit:start
export function authorizeSubmit(principal, request) {
  const allowed = principal.roles.includes(ROLES.employee)
    && principal.tenant === request.tenant
    && principal.id === request.owner;
  requireAllowed(allowed, 'request.submit');
}
// @evidence F.policy.submit:end

// @evidence F.policy.approve:start
export function authorizeApprove(principal, request) {
  const allowed = principal.roles.includes(ROLES.manager)
    && principal.tenant === request.tenant
    && principal.id !== request.owner;
  requireAllowed(allowed, 'request.approve');
}
// @evidence F.policy.approve:end

// @evidence F.policy.read:start
export function authorizeRead(principal, request) {
  const sameTenant = principal.tenant === request.tenant;
  const ownEmployeeRequest = principal.roles.includes(ROLES.employee)
    && principal.id === request.owner;
  const tenantReader = principal.roles.includes(ROLES.manager)
    || principal.roles.includes(ROLES.readonly);
  requireAllowed(sameTenant && (ownEmployeeRequest || tenantReader), 'request.read');
}
// @evidence F.policy.read:end

// @evidence F.receipt:start
export function createReceiptSender() {
  const sent = [];
  const failures = [];
  let failNextSend = false;

  return {
    // @evidence F.receipt.target:start
    async send(request, runtimeTarget) {
      // 只写内存以模拟发送，没有邮件、网络或外部通知。
      if (failNextSend) {
        failNextSend = false;
        throw new Error('合成回执发送失败');
      }
      // 目的地来自运行时参数；只保存其标签，不验证或访问任何地址。
      sent.push({ requestId: request.id, state: request.state, target: runtimeTarget, mode: 'simulated' });
    },
    // @evidence F.receipt.target:end
    recordFailure(request, error) {
      failures.push({ requestId: request.id, message: error.message });
    },
    snapshot: () => structuredClone({ sent, failures }),
    failNext() { failNextSend = true; },
    reset() {
      sent.length = 0;
      failures.length = 0;
      failNextSend = false;
    },
  };
}
// @evidence F.receipt:end

import { REQUESTS } from '../data/fixtures.js';
import { DemoError } from './errors.js';

export function createRepository(initialRequests = REQUESTS) {
  let state;
  const failures = new Set();

  function reset() {
    state = {
      requests: Object.fromEntries(initialRequests.map(request => [request.id, { ...request }])),
      audits: [],
    };
    failures.clear();
  }

  function consumeFailure(point) {
    if (failures.delete(point)) {
      throw new DemoError(503, 'TRANSACTION_FAILED', `合成故障：${point}`);
    }
  }

  // @evidence F.repository.get:start
  function get(id, from = state) {
    const request = from.requests[id];
    if (!request) throw new DemoError(404, 'REQUEST_NOT_FOUND', '申请不存在');
    return { ...request };
  }
  // @evidence F.repository.get:end

  // @evidence F.repository.transaction:start
  // 同步内存事务：先在独立副本写入，全部成功后一次替换已提交状态。
  // 不模拟磁盘耐久性，也不允许回调跨 await，以避免并发副本覆盖。
  function transaction(work) {
    const pending = structuredClone(state);
    const tx = {
      get: id => get(id, pending),
      setState(id, nextState) {
        const request = get(id, pending);
        pending.requests[id] = { ...request, state: nextState };
        return get(id, pending);
      },
      appendAudit(event) {
        consumeFailure('audit-write');
        pending.audits.push({ ...event });
      },
    };
    const result = work(tx);
    if (result?.then) throw new TypeError('此演示仅支持同步事务回调');
    consumeFailure('transaction-commit');
    state = pending;
    return result;
  }
  // @evidence F.repository.transaction:end

  reset();
  return {
    get,
    transaction,
    reset,
    snapshot: () => structuredClone(state),
    // 仅供测试编排，不挂载为 HTTP 接口。
    failNext(point) {
      if (!['audit-write', 'transaction-commit'].includes(point)) {
        throw new TypeError(`未知故障点：${point}`);
      }
      failures.add(point);
    },
  };
}

import { authenticate } from './auth.js';
import { authorizeSubmit, authorizeApprove, authorizeRead } from './policies.js';
import { DemoError } from './errors.js';

export function createRoutes({ repository, handlers }) {
  const routes = [
    // @evidence F.route.submit:start
    {
      method: 'POST', pattern: /^\/requests\/([^/]+)\/submit$/,
      execute(id, context) {
        const principal = authenticate(context);
        const request = repository.get(id);
        authorizeSubmit(principal, request);
        return handlers.submit(principal, request);
      },
    },
    // @evidence F.route.submit:end
    // @evidence F.route.approve:start
    {
      method: 'POST', pattern: /^\/requests\/([^/]+)\/approve$/,
      execute(id, context) {
        const principal = authenticate(context);
        const request = repository.get(id);
        authorizeApprove(principal, request);
        return handlers.approve(principal, request, context.receiptTarget);
      },
    },
    // @evidence F.route.approve:end
    // @evidence F.route.read:start
    {
      method: 'GET', pattern: /^\/requests\/([^/]+)$/,
      execute(id, context) {
        const principal = authenticate(context);
        const request = repository.get(id);
        authorizeRead(principal, request);
        return handlers.read(principal, request);
      },
    },
    // @evidence F.route.read:end
  ];

  return async function dispatch({ method, path, context }) {
    const route = routes.find(candidate => candidate.method === method && candidate.pattern.test(path));
    if (!route) throw new DemoError(404, 'ROUTE_NOT_FOUND', '入口不存在');
    const id = decodeURIComponent(path.match(route.pattern)[1]);
    return route.execute(id, context);
  };
}

import { readFileSync } from 'node:fs';
import { USERS } from '../data/fixtures.js';

// @evidence F.workflow.load:start
export function loadWorkflow() {
  const config = JSON.parse(readFileSync(
    new URL('../config/workflow.json', import.meta.url), 'utf8',
  ));
  return createWorkflow(config);
}
// @evidence F.workflow.load:end

export function createWorkflow(config, users = USERS) {
  // @evidence F.workflow.candidates:start
  // 配置参与实际候选人选择；候选身份不额外授予任何后端操作权限。
  // 原始配置证据还包含 config/workflow.json 全文件。
  function candidatesFor(actor, request) {
    const mappedRoles = config.actorBindings[actor] ?? [];
    return users.filter(user => user.realm === config.realm
      && user.tenant === request.tenant
      && user.roles.some(role => mappedRoles.includes(role)))
      .map(user => user.id);
  }
  // @evidence F.workflow.candidates:end
  return { candidatesFor };
}

let demoSessionToken = 'demo-u1';

export function selectDemoSession(userId) {
  demoSessionToken = `demo-${userId}`;
}

async function request(method, path) {
  const response = await fetch(path, {
    method,
    headers: { 'x-demo-session': demoSessionToken },
  });
  const payload = await response.json();
  return { status: response.status, ...payload };
}

// @evidence F.client.submit:start
export function submitRequest(id) {
  return request('POST', `/requests/${encodeURIComponent(id)}/submit`);
}
// @evidence F.client.submit:end

// @evidence F.client.approve:start
export function approveRequest(id) {
  return request('POST', `/requests/${encodeURIComponent(id)}/approve`);
}
// @evidence F.client.approve:end

// @evidence F.client.read:start
export function readRequest(id) {
  return request('GET', `/requests/${encodeURIComponent(id)}`);
}
// @evidence F.client.read:end

import { ROLES, USERS, REQUESTS } from '../data/fixtures.js';
import { selectDemoSession, submitRequest, approveRequest, readRequest } from './api.js';

const userSelect = document.querySelector('#user');
const requestSelect = document.querySelector('#request');
const output = document.querySelector('#output');
const approveButton = document.querySelector('#approve');

for (const user of USERS) {
  userSelect.add(new Option(`${user.id} · ${user.roles[0]} · ${user.tenant}`, user.id));
}
for (const request of REQUESTS) {
  requestSelect.add(new Option(
    `${request.id} · ${request.state} · ${request.amount} 元 · ${request.tenant}`, request.id,
  ));
}

// @evidence F.ui.approve:start
function refreshApprovalVisibility() {
  const user = USERS.find(candidate => candidate.id === userSelect.value);
  // 可见性只看 manager；租户、所有者、状态、金额全部由后端另行检查。
  approveButton.hidden = !user.roles.includes(ROLES.manager);
}
// @evidence F.ui.approve:end

userSelect.addEventListener('change', () => {
  selectDemoSession(userSelect.value);
  refreshApprovalVisibility();
});

async function run(action) {
  try {
    output.textContent = JSON.stringify(await action(requestSelect.value), null, 2);
  } catch (error) {
    output.textContent = `本地演示请求失败：${error.message}`;
  }
}

// @evidence F.ui.actions:start
document.querySelector('#submit').addEventListener('click', () => run(submitRequest));
document.querySelector('#read').addEventListener('click', () => run(readRequest));
approveButton.addEventListener('click', () => run(approveRequest));
// @evidence F.ui.actions:end
refreshApprovalVisibility();

