export function createReceiptSender() {
  const sent = [];
  const failures = [];
  let failNextSend = false;

  return {
    // @evidence F.receipt.target:start
    async send(request, runtimeTarget) {
      // 只写内存以模拟发送，没有邮件、网络或外部通知。
      if (failNextSend) {
        failNextSend = false;
        throw new Error('合成回执发送失败');
      }
      // 目的地来自运行时参数；只保存其标签，不验证或访问任何地址。
      sent.push({ requestId: request.id, state: request.state, target: runtimeTarget, mode: 'simulated' });
    },
    // @evidence F.receipt.target:end
    recordFailure(request, error) {
      failures.push({ requestId: request.id, message: error.message });
    },
    snapshot: () => structuredClone({ sent, failures }),
    failNext() { failNextSend = true; },
    reset() {
      sent.length = 0;
      failures.length = 0;
      failNextSend = false;
    },
  };
}

function get(id, from = state) {
  const request = from.requests[id];
  if (!request) throw new DemoError(404, 'REQUEST_NOT_FOUND', '申请不存在');
  return { ...request };
}

// 同步内存事务：先在独立副本写入，全部成功后一次替换已提交状态。
// 不模拟磁盘耐久性，也不允许回调跨 await，以避免并发副本覆盖。
function transaction(work) {
  const pending = structuredClone(state);
  const tx = {
    get: id => get(id, pending),
    setState(id, nextState) {
      const request = get(id, pending);
      pending.requests[id] = { ...request, state: nextState };
      return get(id, pending);
    },
    appendAudit(event) {
      consumeFailure('audit-write');
      pending.audits.push({ ...event });
    },
  };
  const result = work(tx);
  if (result?.then) throw new TypeError('此演示仅支持同步事务回调');
  consumeFailure('transaction-commit');
  state = pending;
  return result;
}

{
  method: 'POST', pattern: /^\/requests\/([^/]+)\/submit$/,
  execute(id, context) {
    const principal = authenticate(context);
    const request = repository.get(id);
    authorizeSubmit(principal, request);
    return handlers.submit(principal, request);
  },
},

{
  method: 'POST', pattern: /^\/requests\/([^/]+)\/approve$/,
  execute(id, context) {
    const principal = authenticate(context);
    const request = repository.get(id);
    authorizeApprove(principal, request);
    return handlers.approve(principal, request, context.receiptTarget);
  },
},

{
  method: 'GET', pattern: /^\/requests\/([^/]+)$/,
  execute(id, context) {
    const principal = authenticate(context);
    const request = repository.get(id);
    authorizeRead(principal, request);
    return handlers.read(principal, request);
  },
},

export function loadWorkflow() {
  const config = JSON.parse(readFileSync(
    new URL('../config/workflow.json', import.meta.url), 'utf8',
  ));
  return createWorkflow(config);
}

// 配置参与实际候选人选择；候选身份不额外授予任何后端操作权限。
// 原始配置证据还包含 config/workflow.json 全文件。
function candidatesFor(actor, request) {
  const mappedRoles = config.actorBindings[actor] ?? [];
  return users.filter(user => user.realm === config.realm
    && user.tenant === request.tenant
    && user.roles.some(role => mappedRoles.includes(role)))
    .map(user => user.id);
}

