export function authenticate(context) {
  // 只读取宿主绑定的 session；不接收 body.userId/body.roles/body.tenant。
  const principal = context.session?.principal;
  if (!principal?.authenticated || principal.realm !== REALM) {
    throw new DemoError(401, 'AUTHENTICATION_REQUIRED', '需要有效的合成演示会话');
  }
  return principal;
}

function requireAllowed(allowed, permission) {
  // B0：适用允许规则任一满足即允许；无匹配规则默认拒绝。
  if (!allowed) {
    throw new DemoError(403, 'FORBIDDEN', `未满足 ${permission} 的授权条件`);
  }
}

function consumeFailure(point) {
  if (failures.delete(point)) {
    throw new DemoError(503, 'TRANSACTION_FAILED', `合成故障：${point}`);
  }
}

